'use client';

import { useEffect, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Sheet, SheetContent, SheetTitle } from '@/registry/ndeko/ui/sheet';

import { AppSidebar } from './app-sidebar';
import {
  CURRENT_USER_ID,
  NAV_GROUPS,
  PEOPLE,
  WORKSPACES,
  personOf,
  type NavItem,
  type PageId,
} from './data';
import { OverviewPage } from './overview-page';
import { ProjectHealthPage } from './project-health-page';
import { CommandPalette } from './search-palette';
import { TopBar } from './top-bar';
import { WeeklyReportPage } from './weekly-report-page';

const NAV_ITEMS = NAV_GROUPS.flatMap((group) => group.items);

const NO_COUNTS = {};

function navItemOf(pageId: PageId): NavItem {
  const item = NAV_ITEMS.find((candidate) => candidate.id === pageId);
  if (item) {
    return item;
  }
  return NAV_ITEMS[0];
}

function ancestorOf(pageId: PageId, workspaceName: string) {
  const group = NAV_GROUPS.find((candidate) =>
    candidate.items.some((item) => item.id === pageId)
  );
  if (group?.team) {
    return group.team.name;
  }
  if (group?.label) {
    return workspaceName;
  }
  return undefined;
}

function isPaletteShortcut(event: KeyboardEvent) {
  const isKKey = event.key.toLowerCase() === 'k';
  const hasModifier = event.metaKey || event.ctrlKey;
  return isKKey && hasModifier;
}

function keepWorkspace() {
  return undefined;
}

export default function Application02() {
  const [activePageId, setActivePageId] = useState<PageId>('overview');
  const [isSidebarHidden, setIsSidebarHidden] = useState(false);
  const [isNavigationOpen, setIsNavigationOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);

  const workspace = WORKSPACES[0];
  const activePage = navItemOf(activePageId);
  const ancestor = ancestorOf(activePageId, workspace.name);
  const currentUser = personOf(CURRENT_USER_ID);

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (isPaletteShortcut(event)) {
        event.preventDefault();
        setIsPaletteOpen((isOpen) => !isOpen);
      }
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  function navigate(pageId: PageId) {
    setActivePageId(pageId);
    setIsNavigationOpen(false);
  }

  function openSearch() {
    setIsNavigationOpen(false);
    setIsPaletteOpen(true);
  }

  function hideSidebar() {
    setIsSidebarHidden(true);
  }

  function showSidebar() {
    setIsSidebarHidden(false);
  }

  function openNavigation() {
    setIsNavigationOpen(true);
  }

  const sidebarProps = {
    workspaces: WORKSPACES,
    workspace,
    onWorkspaceChange: keepWorkspace,
    groups: NAV_GROUPS,
    activePageId,
    counts: NO_COUNTS,
    person: currentUser,
    onNavigate: navigate,
    onOpenSearch: openSearch,
  };

  return (
    <div className='bg-sidebar text-foreground flex h-dvh min-h-0 w-full md:p-2'>
      <aside aria-label='Sidebar' className='hidden shrink-0 md:block'>
        <AnimatedSize
          axis='width'
          inert={isSidebarHidden}
          className='m-0 h-full'
          contentClassName={cn('h-full p-0', isSidebarHidden && 'w-0')}
        >
          <div className='h-full w-60 pr-2'>
            <AppSidebar {...sidebarProps} onHide={hideSidebar} />
          </div>
        </AnimatedSize>
      </aside>
      <Sheet open={isNavigationOpen} onOpenChange={setIsNavigationOpen}>
        <SheetContent
          side='left'
          showCloseButton={false}
          className='bg-sidebar w-72 gap-0 p-2'
        >
          <SheetTitle className='sr-only'>Navigation</SheetTitle>
          <AppSidebar {...sidebarProps} />
        </SheetContent>
      </Sheet>
      <main className='bg-background md:hairline-ring md:ring-border flex min-w-0 flex-1 flex-col overflow-clip md:rounded-xl md:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <TopBar
          page={activePage}
          ancestor={ancestor}
          people={PEOPLE}
          isSidebarHidden={isSidebarHidden}
          onShowSidebar={showSidebar}
          onOpenNavigation={openNavigation}
        />
        {activePageId === 'overview' && <OverviewPage />}
        {activePageId === 'weekly-report' && <WeeklyReportPage />}
        {activePageId === 'project-health' && <ProjectHealthPage />}
      </main>
      <CommandPalette
        open={isPaletteOpen}
        onOpenChange={setIsPaletteOpen}
        groups={NAV_GROUPS}
        onNavigate={navigate}
      />
    </div>
  );
}

'use client';

import { useId } from 'react';

import { LayoutIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { AccountMenu } from './account-menu';
import type { NavGroup, NavItem, PageId, Person, Workspace } from './data';
import { SearchTrigger } from './search-palette';
import { EntityTile, NavRow } from './sidebar-parts';
import { WorkspaceSwitcher } from './workspace-switcher';

export type PageCounts = Partial<Record<PageId, number>>;

type AppSidebarProps = {
  workspaces: Workspace[];
  workspace: Workspace;
  onWorkspaceChange: (workspaceId: string) => void;
  groups: NavGroup[];
  activePageId: PageId;
  counts: PageCounts;
  person: Person;
  onNavigate: (pageId: PageId) => void;
  onOpenSearch: () => void;
  onHide?: () => void;
};

function GroupLabel({ group }: { group: NavGroup }) {
  if (group.team) {
    return (
      <p className='text-muted-foreground flex h-6 items-center gap-2 px-2 text-xs font-medium'>
        <EntityTile entity={group.team} size='xs' />
        {group.team.name}
      </p>
    );
  }
  if (group.label) {
    return (
      <p className='text-muted-foreground flex h-6 items-center px-2 text-xs font-medium'>
        {group.label}
      </p>
    );
  }
  return null;
}

export function AppSidebar({
  workspaces,
  workspace,
  onWorkspaceChange,
  groups,
  activePageId,
  counts,
  person,
  onNavigate,
  onOpenSearch,
  onHide,
}: AppSidebarProps) {
  const indicatorId = useId();
  const canHide = Boolean(onHide);

  function selectItem(item: NavItem) {
    onNavigate(item.id);
  }

  return (
    <div className='flex h-full min-h-0 flex-col gap-3'>
      <div className='flex flex-col gap-2'>
        <div className='flex items-center gap-1'>
          <WorkspaceSwitcher
            workspaces={workspaces}
            current={workspace}
            onSelect={onWorkspaceChange}
          />
          {canHide && (
            <Button
              variant='ghost'
              size='icon-sm'
              aria-label='Hide sidebar'
              onClick={onHide}
              className='text-muted-foreground'
            >
              <LayoutIcon />
            </Button>
          )}
        </div>
        <div className='flex items-center'>
          <SearchTrigger onOpen={onOpenSearch} />
        </div>
      </div>
      <nav
        aria-label='Main'
        className='-mx-2 flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-2'
      >
        {groups.map((group) => (
          <div key={group.id} className='flex flex-col gap-0.5'>
            <GroupLabel group={group} />
            <ul className='flex flex-col gap-px'>
              {group.items.map((item) => (
                <NavRow
                  key={item.id}
                  item={item}
                  isActive={item.id === activePageId}
                  indicatorId={indicatorId}
                  count={counts[item.id]}
                  onSelect={selectItem}
                />
              ))}
            </ul>
          </div>
        ))}
      </nav>
      <AccountMenu person={person} />
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { Entity, NavItem, Person } from './data';

export const NAV_ROW = [
  'relative flex h-7 w-full min-w-0 items-center gap-2 rounded-md px-2 text-left text-[13px] font-medium text-foreground outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
  "[&_svg]:pointer-events-none [&_svg]:relative [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
].join(' ');

const INDICATOR_TRAVEL: Transition = {
  duration: 0.25,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return INDICATOR_TRAVEL;
}

/** The one highlight of the active row. It travels from the old row to the new one. */
export function ActiveRowIndicator({ layoutId }: { layoutId: string }) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.span
      aria-hidden='true'
      layoutId={layoutId}
      transition={travelOf(shouldReduceMotion)}
      className='bg-foreground/[0.07] absolute inset-0 rounded-md'
    />
  );
}

const TILE_SIZE = {
  xs: 'size-4 rounded-[4px] text-[9px]',
  sm: 'size-5 rounded-[5px] text-[10px]',
  md: 'size-6 rounded-md text-[11px]',
} as const;

export function EntityTile({
  entity,
  size = 'md',
  className,
}: {
  entity: Entity;
  size?: keyof typeof TILE_SIZE;
  className?: string;
}) {
  const tileStyle = { '--gem': entity.color } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={tileStyle}
      className={cn(
        'gem-plate inline-flex shrink-0 items-center justify-center font-semibold',
        TILE_SIZE[size],
        className
      )}
    >
      {entity.initials}
    </span>
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={className}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

export function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

type NavRowProps = {
  item: NavItem;
  isActive: boolean;
  indicatorId: string;
  count?: number;
  onSelect: (item: NavItem) => void;
};

export function NavRow({
  item,
  isActive,
  indicatorId,
  count = 0,
  onSelect,
}: NavRowProps) {
  const hasCount = count > 0;
  const ItemIcon = item.icon;
  const ariaCurrent = ariaCurrentOf(isActive);

  function selectItem() {
    onSelect(item);
  }

  return (
    <li>
      <button
        type='button'
        aria-current={ariaCurrent}
        onClick={selectItem}
        className={NAV_ROW}
      >
        {isActive && <ActiveRowIndicator layoutId={indicatorId} />}
        <ItemIcon />
        <span className='relative min-w-0 flex-1 truncate'>{item.label}</span>
        {hasCount && (
          <MotionNumber
            value={count}
            className='text-muted-foreground text-xs font-normal'
          />
        )}
      </button>
    </li>
  );
}

'use client';

import {
  ChevronsUpDownIcon,
  PlusIcon,
  SettingsIcon,
} from '@/registry/ndeko/lib/icons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Workspace } from './data';
import { EntityTile } from './sidebar-parts';

const TRIGGER = [
  'flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md px-1.5 text-left outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 data-popup-open:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
].join(' ');

function memberCountLabelOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}

type WorkspaceSwitcherProps = {
  workspaces: Workspace[];
  current: Workspace;
  onSelect: (workspaceId: string) => void;
};

export function WorkspaceSwitcher({
  workspaces,
  current,
  onSelect,
}: WorkspaceSwitcherProps) {
  function selectWorkspace(value: unknown) {
    if (typeof value === 'string') {
      onSelect(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Workspace: ${current.name}`}
            className={TRIGGER}
          />
        }
      >
        <EntityTile entity={current} />
        <span className='min-w-0 flex-1 truncate text-[13px] font-semibold'>
          {current.name}
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-64'>
        <DropdownMenuLabel>Workspaces</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          value={current.id}
          onValueChange={selectWorkspace}
        >
          {workspaces.map((workspace) => (
            <DropdownMenuRadioItem
              key={workspace.id}
              value={workspace.id}
              closeOnClick
              className='h-9'
            >
              <EntityTile entity={workspace} size='sm' />
              <span className='min-w-0 flex-1 truncate'>{workspace.name}</span>
              <Kbd aria-hidden='true'>{workspace.memberCount}</Kbd>
              <span className='sr-only'>
                {memberCountLabelOf(workspace.memberCount)}
              </span>
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <SettingsIcon />
          Workspace settings
        </DropdownMenuItem>
        <DropdownMenuItem>
          <PlusIcon />
          Add workspace
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { SearchIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/registry/ndeko/ui/command';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { NavGroup, PageId } from './data';

function headingOf(group: NavGroup) {
  if (group.team) {
    return group.team.name;
  }
  if (group.label) {
    return group.label;
  }
  return 'Personal';
}

export function SearchTrigger({ onOpen }: { onOpen: () => void }) {
  return (
    <button
      type='button'
      onClick={onOpen}
      className={cn(
        CONTROL_RECIPE,
        'text-muted-foreground flex h-8 min-w-0 flex-1 cursor-pointer items-center gap-2 px-2.5 text-left'
      )}
    >
      <SearchIcon className='size-4 shrink-0' />
      <span className='min-w-0 flex-1 truncate'>Search</span>
      <Kbd>⌘K</Kbd>
    </button>
  );
}

type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  groups: NavGroup[];
  onNavigate: (pageId: PageId) => void;
};

export function CommandPalette({
  open,
  onOpenChange,
  groups,
  onNavigate,
}: CommandPaletteProps) {
  function closePalette() {
    onOpenChange(false);
  }

  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      title='Search'
      description='Go to a report'
    >
      <CommandInput placeholder='Go to a report' />
      <CommandList>
        <CommandEmpty>Nothing matches. Try the name of a report.</CommandEmpty>
        {groups.map((group) => (
          <CommandGroup key={group.id} heading={headingOf(group)}>
            {group.items.map((item) => {
              const ItemIcon = item.icon;

              function goToPage() {
                closePalette();
                onNavigate(item.id);
              }

              return (
                <CommandItem
                  key={item.id}
                  value={`${group.id} ${item.label}`}
                  onSelect={goToPage}
                >
                  <ItemIcon />
                  {item.label}
                </CommandItem>
              );
            })}
          </CommandGroup>
        ))}
      </CommandList>
    </CommandDialog>
  );
}

'use client';

import {
  ChevronsUpDownIcon,
  CommandIcon,
  LifeBuoyIcon,
  LogOutIcon,
  SettingsIcon,
  UserIcon,
} from '@/registry/ndeko/lib/icons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Person } from './data';
import { PersonAvatar } from './sidebar-parts';

const TRIGGER = [
  'flex h-9 w-full min-w-0 items-center gap-2 rounded-md px-1.5 text-left outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 data-popup-open:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
].join(' ');

export function AccountMenuItems({ person }: { person: Person }) {
  return (
    <>
      <div className='flex items-center gap-2.5 px-2 py-2'>
        <PersonAvatar person={person} />
        <div className='min-w-0'>
          <p className='truncate text-[13px] font-medium'>{person.name}</p>
          <p className='text-muted-foreground truncate text-xs'>
            {person.role}
          </p>
        </div>
      </div>
      <DropdownMenuSeparator />
      <DropdownMenuItem>
        <UserIcon />
        Profile
      </DropdownMenuItem>
      <DropdownMenuItem>
        <SettingsIcon />
        Preferences
      </DropdownMenuItem>
      <DropdownMenuItem>
        <CommandIcon />
        Keyboard shortcuts
        <Kbd className='ml-auto'>?</Kbd>
      </DropdownMenuItem>
      <DropdownMenuItem>
        <LifeBuoyIcon />
        Help and docs
      </DropdownMenuItem>
      <DropdownMenuSeparator />
      <DropdownMenuItem variant='destructive'>
        <LogOutIcon />
        Log out
      </DropdownMenuItem>
    </>
  );
}

export function AccountMenu({ person }: { person: Person }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Account: ${person.name}`}
            className={TRIGGER}
          />
        }
      >
        <PersonAvatar person={person} className='size-6 text-[10px]' />
        <span className='min-w-0 flex-1 truncate text-[13px] font-medium'>
          {person.name}
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent side='top' align='start' className='w-60'>
        <AccountMenuItems person={person} />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { LayoutIcon, MenuIcon } from '@/registry/ndeko/lib/icons';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/registry/ndeko/ui/breadcrumb';
import { Button } from '@/registry/ndeko/ui/button';

import type { NavItem, Person } from './data';
import { PersonAvatar } from './sidebar-parts';

const STACK_LIMIT = 4;

function AvatarStack({ people }: { people: Person[] }) {
  const shown = people.slice(0, STACK_LIMIT);
  const hiddenCount = people.length - shown.length;
  const hasHidden = hiddenCount > 0;

  return (
    <div
      role='group'
      aria-label='Team members'
      className='hidden items-center sm:flex'
    >
      {shown.map((person) => (
        <PersonAvatar
          key={person.id}
          person={person}
          className='ring-background -ml-1.5 size-6 text-[10px] ring-2 first:ml-0'
        />
      ))}
      {hasHidden && (
        <span className='bg-muted text-muted-foreground ring-background -ml-1.5 inline-flex size-6 items-center justify-center rounded-full text-[10px] font-medium tabular-nums ring-2'>
          +{hiddenCount}
        </span>
      )}
    </div>
  );
}

type TopBarProps = {
  page: NavItem;
  ancestor?: string;
  people: Person[];
  isSidebarHidden: boolean;
  onShowSidebar: () => void;
  onOpenNavigation: () => void;
};

export function TopBar({
  page,
  ancestor,
  people,
  isSidebarHidden,
  onShowSidebar,
  onOpenNavigation,
}: TopBarProps) {
  const PageIcon = page.icon;
  const hasAncestor = Boolean(ancestor);

  return (
    <header className='hairline-b border-border flex h-11 shrink-0 items-center gap-2 px-3 md:px-4'>
      <Button
        variant='ghost'
        size='icon-sm'
        aria-label='Open navigation'
        onClick={onOpenNavigation}
        className='text-muted-foreground md:hidden'
      >
        <MenuIcon />
      </Button>
      {isSidebarHidden && (
        <Button
          variant='ghost'
          size='icon-sm'
          aria-label='Show sidebar'
          onClick={onShowSidebar}
          className='text-muted-foreground hidden md:inline-flex'
        >
          <LayoutIcon />
        </Button>
      )}
      <Breadcrumb className='min-w-0'>
        <BreadcrumbList className='flex-nowrap'>
          <li aria-hidden='true' className='flex'>
            <PageIcon className='text-muted-foreground size-4 shrink-0' />
          </li>
          {hasAncestor && (
            <>
              <BreadcrumbItem className='hidden sm:inline-flex'>
                {ancestor}
              </BreadcrumbItem>
              <BreadcrumbSeparator className='hidden sm:block' />
            </>
          )}
          <BreadcrumbItem className='min-w-0'>
            <BreadcrumbPage className='truncate'>{page.label}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>
      <div className='ml-auto flex items-center gap-2'>
        <AvatarStack people={people} />
      </div>
    </header>
  );
}

'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Skeleton } from '@/registry/ndeko/ui/skeleton';

import {
  PERIODS,
  WORKSPACE,
  type MetricDefinition,
  type MetricId,
  type PeriodId,
} from './data';
import {
  chartPointsOf,
  csvRowsOf,
  figuresOf,
  formatMetric,
  metricOf,
  periodOf,
} from './overview-figures';
import { MetricStrip } from './metric-strip';
import {
  ExportButton,
  PeriodSwitch,
  REPORT_SURFACE,
  ReportToolbar,
  downloadCsv,
  useSimulatedLoad,
  type PeriodOption,
} from './report-frame';
import { TrendChart } from './trend-chart';

const PERIOD_OPTIONS: PeriodOption<PeriodId>[] = PERIODS.map((period) => ({
  id: period.id,
  label: period.switchLabel,
}));

const SKELETON_CELLS = ['tracked', 'closed', 'billable', 'review'];

function periodKeyOf(periodId: PeriodId) {
  return periodId;
}

function peopleLabelOf(count: number) {
  if (count === 1) {
    return '1 person';
  }
  return `${count} people`;
}

function formatterOf(metric: MetricDefinition) {
  return (value: number) => formatMetric(metric, value);
}

function OverviewSkeleton() {
