import { DurationFigure } from './duration-figure';
import {
  averageWorkdayMinutesOf,
  csvRowsOf,
  dayBarsOf,
  memberOf,
  rankingOf,
  totalMinutesOf,
  weekOf,
  workingDaysSoFarOf,
  type Scope,
  type WeekQuery,
} from './weekly-figures';
import { ProjectRanking } from './project-ranking';
import {
  ExportButton,
  PeriodSwitch,
  REPORT_SURFACE,
  ReportToolbar,
  downloadCsv,
  useSimulatedLoad,
  type PeriodOption,
} from './report-frame';

type ScopeOption = { value: Scope; label: string; member: Member | null };

const WEEK_OPTIONS: PeriodOption<Week['id']>[] = WEEKS.map((week) => ({
  id: week.id,
  label: `Week ${week.number}`,
}));

const SCOPE_OPTIONS: ScopeOption[] = [
  { value: 'everyone', label: 'Everyone', member: null },
  ...MEMBERS.map((member) => ({
    value: member.id,
    label: member.name,
    member,
  })),
];

const INITIAL_QUERY: WeekQuery = { weekId: 'w45', scope: 'everyone' };

const SKELETON_ROWS = ['first', 'second', 'third', 'fourth'];

function queryKeyOf(query: WeekQuery) {
  return `${query.weekId}:${query.scope}`;
}

function dayCountLabelOf(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${count} ${plural}`;
}

function dayNoteOf(week: Week) {
  if (week.todayIndex === null) {
    return 'Monday to Sunday';
  }
  const today = week.days[week.todayIndex];
  const lastIndex = week.days.length - 1;
  const aheadCount = lastIndex - week.todayIndex;
  const aheadLabel = dayCountLabelOf(aheadCount, 'day', 'days');
  return `${today.name} so far, ${aheadLabel} ahead`;
}

function scopeLabelOf(member: Member | null) {
  if (member) {
    return member.name;
  }
  return TEAM_NAME;
}

function firstNameOf(member: Member | null) {
  if (!member) {
    return 'the team';
  }
  const [firstName] = member.name.split(' ');
  return firstName;
}

function MemberFace({ member }: { member: Member }) {
  return (
    <Avatar className='size-5 text-[9px]'>
      {member.avatar && <AvatarImage src={member.avatar} alt='' />}
      <AvatarFallback>{member.initials}</AvatarFallback>
    </Avatar>
  );
}

function WeekSkeleton() {
  return (
    <div
      aria-hidden='true'
      className='grid gap-4 lg:grid-cols-[minmax(0,1.6fr)_minmax(0,1fr)]'
    >
      <div className={cn(REPORT_SURFACE, 'flex flex-col gap-5 p-5')}>
        <Skeleton className='h-3.5 w-28' />
        <div className='flex gap-8'>
          <Skeleton className='h-9 w-24' />
          <Skeleton className='h-9 w-24' />
        </div>
        <Skeleton className='h-[204px] w-full rounded-lg' />
      </div>
      <div className={cn(REPORT_SURFACE, 'flex flex-col gap-4 p-5')}>
        <Skeleton className='h-3.5 w-36' />
        {SKELETON_ROWS.map((row) => (
          <div key={row} className='flex flex-col gap-2'>
            <Skeleton className='h-3 w-full' />
            <Skeleton className='h-1 w-3/4' />
          </div>
        ))}
      </div>
    </div>
  );
}

export function WeeklyReportPage() {
  const load = useSimulatedLoad<WeekQuery>(INITIAL_QUERY, queryKeyOf);
  const shownQuery = load.loaded ?? load.requested;
  const week = weekOf(shownQuery.weekId);
  const member = memberOf(shownQuery.scope);
  const bars = dayBarsOf(shownQuery);
  const totalMinutes = totalMinutesOf(bars);
  const averageMinutes = averageWorkdayMinutesOf(bars, week);
  const workingDays = workingDaysSoFarOf(week);
  const ranking = rankingOf(shownQuery);
  const isEmptyWeek = totalMinutes === 0;
  const scopeLabel = scopeLabelOf(member);
  const title = `Week ${week.number}`;
  const meta = `${week.rangeLabel} · ${scopeLabel}`;
  const dayNote = dayNoteOf(week);
  const workingDaysLabel = dayCountLabelOf(
    workingDays,
    'working day',
    'working days'
  );
  const projectCountLabel = dayCountLabelOf(
    ranking.projectCount,
    'project',
    'projects'
  );
  const chartTitle = `Hours by day in week ${week.number}, ${scopeLabel}`;
  const firstName = firstNameOf(member);
  const emptyLine = `Nothing to rank for ${firstName} in week ${week.number}`;

  function changeWeek(weekId: Week['id']) {
    load.request((previous) => ({ ...previous, weekId }));
  }

  function changeScope(value: unknown) {
    const option = SCOPE_OPTIONS.find((candidate) => candidate.value === value);
    if (!option) {
      return;
    }
    load.request((previous) => ({ ...previous, scope: option.value }));
  }

  function showEveryone() {
    load.request((previous) => ({ ...previous, scope: 'everyone' }));
  }

  function exportWeek() {
    const rows = csvRowsOf(bars);
    const fileName = `tidewell-week-${week.number}-${shownQuery.scope}.csv`;
    downloadCsv(fileName, rows);
  }

  return (
    <div className='min-h-0 w-full flex-1 overflow-y-auto'>
      <ReportToolbar title={title} meta={meta}>
        <Select
          items={SCOPE_OPTIONS}
          value={load.requested.scope}
          onValueChange={changeScope}
        >
          <SelectTrigger aria-label='Whose time' className='w-40 sm:w-44'>
            <SelectValue />
          </SelectTrigger>
          <SelectContent align='end'>
            {SCOPE_OPTIONS.map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.member && <MemberFace member={option.member} />}
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <ExportButton disabled={load.isFirstLoad} onExport={exportWeek} />
      </ReportToolbar>
      <div className='mx-auto flex w-full max-w-5xl flex-col gap-4 px-4 py-5 md:px-6'>
        <PeriodSwitch
          label='Week'
          options={WEEK_OPTIONS}
          value={load.requested.weekId}
          isUpdating={load.isUpdating}
          onValueChange={changeWeek}
        />
        {load.isFirstLoad && <WeekSkeleton />}
        {!load.isFirstLoad && (
          <div
            aria-busy={load.isUpdating}
            className='grid items-start gap-4 lg:grid-cols-[minmax(0,1.6fr)_minmax(0,1fr)]'
          >
            <section
              aria-label='Hours by day'
              className={cn(REPORT_SURFACE, 'flex flex-col gap-5 p-5')}
            >
              <div className='flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1'>
                <div className='flex flex-col gap-0.5'>
                  <h2 className='text-sm font-medium'>Hours by day</h2>
                  <p className='text-muted-foreground text-xs'>{dayNote}</p>
                </div>
                <span className='text-muted-foreground text-xs'>
                  Illustrative figures
                </span>
              </div>
              <div className='flex flex-wrap gap-x-10 gap-y-3'>
                <div className='flex flex-col gap-0.5'>
                  <span className='text-muted-foreground text-xs'>Tracked</span>
                  <DurationFigure
                    minutes={totalMinutes}
                    className='text-lg leading-7 font-semibold'
                  />
                </div>
                <div className='flex flex-col gap-0.5'>
                  <span className='text-muted-foreground text-xs'>
                    Average a working day
                  </span>
                  <DurationFigure
                    minutes={averageMinutes}
                    className='text-lg leading-7 font-semibold'
                  />
                  <span className='text-muted-foreground text-xs'>
                    {`Over ${workingDaysLabel}`}
                  </span>
                </div>
              </div>
              <DayBars
                title={chartTitle}
                bars={bars}
                emptyState={
                  isEmptyWeek && (
                    <div className='bg-card flex flex-col items-center gap-3 rounded-lg px-3 py-2'>
                      <p className='text-[13px] font-medium text-balance'>
                        {`${scopeLabel} has no time in week ${week.number}`}
                      </p>
                      <Button
                        variant='outline'
                        size='sm'
                        onClick={showEveryone}
                      >
                        Show everyone
                      </Button>
                    </div>
                  )
                }
              />
            </section>
            <section
              aria-label='Where the time went'
              className={cn(REPORT_SURFACE, 'flex flex-col gap-3 p-5')}
            >
              <div className='flex items-baseline justify-between gap-3'>
                <h2 className='text-sm font-medium'>Where the time went</h2>
                <span className='text-muted-foreground text-xs tabular-nums'>
                  {projectCountLabel}
                </span>
              </div>
              <ProjectRanking
                rows={ranking.rows}
                other={ranking.other}
                emptyLine={emptyLine}
              />
            </section>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import {
  ChartBubble,
  bubbleAlignOf,
  columnCenterOf,
  niceScale,
  percentOf,
  useActiveIndex,
} from './chart-kit';
import { formatDuration, type DayBar } from './weekly-figures';

const PLOT_HEIGHT = 180;

const MAX_LINES = 4;

const EMPTY_SCALE_HOURS = 8;

const STUB_PX = 3;

const BUBBLE_GAP_PX = 8;

const MOVE_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

function moveTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE_TRANSITION;
}

function scaleHoursOf(bars: DayBar[]) {
  const minutes = bars.map((bar) => bar.minutes);
  const maxMinutes = Math.max(...minutes);
  if (maxMinutes === 0) {
    return EMPTY_SCALE_HOURS;
  }
  return maxMinutes / 60;
}

function filledRatioOf(bar: DayBar, topMinutes: number) {
  if (bar.minutes === 0) {
    return STUB_PX / PLOT_HEIGHT;
  }
  return bar.minutes / topMinutes;
}

function hiddenShareOf(ratio: number) {
  const hidden = 1 - ratio;
  return percentOf(hidden);
}

function tickTopOf(tickHours: number, topHours: number) {
  const ratio = tickHours / topHours;
  const fromBottom = ratio * PLOT_HEIGHT;
  return PLOT_HEIGHT - fromBottom;
}

function bubbleTopOf(bar: DayBar, topMinutes: number) {
  if (bar.isAhead) {
    const middle = PLOT_HEIGHT / 2;
    return middle - BUBBLE_GAP_PX;
  }
  const ratio = filledRatioOf(bar, topMinutes);
  const barHeight = ratio * PLOT_HEIGHT;
  const barTop = PLOT_HEIGHT - barHeight;
  return barTop - BUBBLE_GAP_PX;
}

function bubbleValueOf(bar: DayBar) {
  if (bar.isAhead) {
    return 'Day ahead';
  }
  return formatDuration(bar.minutes);
}

function bubbleLabelOf(bar: DayBar) {
  if (bar.isToday) {
    return `${bar.label}, so far`;
  }
  return bar.label;
}

function tableValueOf(bar: DayBar) {
  if (bar.isAhead) {
    return 'Day ahead';
  }
  return formatDuration(bar.minutes);
}

type DayBarsProps = {
  title: string;
  bars: DayBar[];
  /** Shown over the empty plot, which keeps its hour lines and day slots. */
  emptyState?: React.ReactNode;
};

/** Hours per day as rounded bars. Bars move to their new height when the data changes, never on mount. */
export function DayBars({ title, bars, emptyState }: DayBarsProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const transition = moveTransitionOf(shouldReduceMotion);
  const count = bars.length;
  const scaleHours = scaleHoursOf(bars);
  const scale = niceScale(scaleHours, MAX_LINES);
  const topMinutes = scale.top * 60;
  const defaultIndex = defaultIndexOf(bars);
  const reading = useActiveIndex(count, defaultIndex);
  const shownBar = bars[reading.shownIndex];
  const shownCenter = columnCenterOf(reading.shownIndex, count);
  const shownLeft = percentOf(shownCenter);
  const bubbleTop = bubbleTopOf(shownBar, topMinutes);
  const bubbleAlign = bubbleAlignOf(reading.shownIndex, count);
  const bubbleLabel = bubbleLabelOf(shownBar);
  const bubbleValue = bubbleValueOf(shownBar);
  const readingText = `${bubbleLabel}: ${bubbleValue}`;
  const plotHeight = { height: PLOT_HEIGHT };

  return (
    <div className='flex flex-col'>
      <div className='grid grid-cols-[2.5rem_minmax(0,1fr)]'>
        <div aria-hidden='true' className='relative' style={plotHeight}>
          {scale.ticks.map((tick) => {
            const top = tickTopOf(tick, scale.top);

            return (
              <span
                key={tick}
                className='text-muted-foreground absolute right-2.5 -translate-y-1/2 text-[11px] tabular-nums'
                style={{ top }}
              >
                {`${tick}h`}
              </span>
            );
          })}
        </div>
        <div
          role='group'
          tabIndex={0}
          aria-label={`${title}. Use the arrow keys to read each day.`}
          className='focus-visible:ring-ring/25 relative touch-pan-y rounded-md outline-none focus-visible:ring-[3px]'
          style={plotHeight}
          {...reading.handlers}
        >
          {scale.ticks.map((tick) => {
            const top = tickTopOf(tick, scale.top);

            return (
              <span
                key={tick}
                aria-hidden='true'
                className='hairline-t border-border absolute inset-x-0'
                style={{ top }}
              />
            );
          })}
          <div aria-hidden='true' className='absolute inset-0 flex'>
            {bars.map((bar, index) => {
              const isShown = index === reading.shownIndex;
              const isDimmed = reading.isActive && !isShown;
              const isEmptyDay = bar.minutes === 0;
              const ratio = filledRatioOf(bar, topMinutes);
              const offset = hiddenShareOf(ratio);

              return (
                <div key={bar.label} className='flex flex-1 justify-center'>
                  {bar.isAhead && (
                    <span className='hairline-border border-foreground/15 h-full w-[56%] max-w-10 rounded-md border-dashed' />
                  )}
                  {!bar.isAhead && (
                    <span className='relative h-full w-[56%] max-w-10 overflow-hidden'>
                      <motion.span
                        initial={false}
                        animate={{ y: offset }}
                        transition={transition}
                        className={cn(
                          'absolute inset-0 rounded-t-[5px] transition-opacity duration-150',
                          isEmptyDay && 'bg-foreground/15',
                          !isEmptyDay && 'bg-primary',
                          isDimmed && 'opacity-55'
                        )}
                      />
                    </span>
                  )}
                </div>
              );
            })}
          </div>
          {emptyState && (
            <div className='pointer-events-none absolute inset-0 flex items-center justify-center px-4 text-center *:pointer-events-auto'>
              {emptyState}
            </div>
          )}
          <ChartBubble
            left={shownLeft}
            top={bubbleTop}
            align={bubbleAlign}
            isVisible={reading.isActive}
          >
            <span className='text-muted-foreground'>{bubbleLabel}</span>
            <span className='text-[13px] font-medium tabular-nums'>
              {bubbleValue}
            </span>
          </ChartBubble>
        </div>
        <span aria-hidden='true' />
        <div aria-hidden='true' className='mt-2 flex'>
          {bars.map((bar) => (
            <span
              key={bar.label}
              className={cn(
                'text-muted-foreground flex-1 text-center text-[11px] whitespace-nowrap tabular-nums',
                bar.isToday && 'text-foreground font-medium'
              )}
            >
              {bar.axisLabel}
            </span>
          ))}
        </div>
      </div>
      <span aria-live='polite' className='sr-only'>
        {reading.isReadingByKeys && readingText}
      </span>
      <table className='sr-only'>
        <caption>{title}</caption>
        <thead>
          <tr>
            <th scope='col'>Day</th>
            <th scope='col'>Tracked time</th>
          </tr>
        </thead>
        <tbody>
          {bars.map((bar) => (
            <tr key={bar.label}>
              <th scope='row'>{bubbleLabelOf(bar)}</th>
              <td>{tableValueOf(bar)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** The bubble opens on today, or on the last day with time when the week is over. */
function defaultIndexOf(bars: DayBar[]) {
  const todayIndex = bars.findIndex((bar) => bar.isToday);
  if (todayIndex >= 0) {
    return todayIndex;
  }
  let lastWorkedIndex = 0;
  bars.forEach((bar, index) => {
    if (bar.minutes > 0) {
      lastWorkedIndex = index;
    }
  });
  return lastWorkedIndex;
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import { DurationFigure } from './duration-figure';
import type { OtherProjects, RankedProject } from './weekly-figures';

const ROW_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const ROW_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const MOVE_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

const ROW_VARIANTS: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: ROW_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: ROW_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: ROW_OUT },
  shown: { opacity: 1, transition: ROW_IN },
};

function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_VARIANTS;
}

function moveTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE_TRANSITION;
}

function meterToneOf(rank: number) {
  if (rank === 0) {
    return 'bg-primary';
  }
  return 'bg-foreground/25';
}

function otherLabelOf(count: number) {
  if (count === 1) {
    return '1 other project';
  }
  return `${count} other projects`;
}

function percentAmountOf(share: number) {
  const percent = share * 100;
  return Math.round(percent);
}

type ShareMeterProps = {
  share: number;
  tone: string;
  transition: Transition;
};

/** A thin meter whose fill slides into place, so its rounded end never stretches. */
function ShareMeter({ share, tone, transition }: ShareMeterProps) {
  const hiddenShare = 1 - share;
  const hiddenPercent = hiddenShare * 100;
  const offset = `-${hiddenPercent}%`;

  return (
    <span className='bg-foreground/[0.06] relative block h-1 overflow-hidden rounded-full'>
      <motion.span
        initial={false}
        animate={{ x: offset }}
        transition={transition}
        className={cn('absolute inset-0 rounded-full', tone)}
      />
    </span>
  );
}

type RankRowProps = {
  label: string;
  minutes: number;
  share: number;
  tone: string;
  transition: Transition;
  isMuted?: boolean;
};

function RankRow({
  label,
  minutes,
  share,
  tone,
  transition,
  isMuted,
}: RankRowProps) {
  const shareAmount = percentAmountOf(share);

  return (
    <div className='grid grid-cols-[2.5rem_minmax(0,1fr)_auto] items-baseline gap-x-2 gap-y-1.5 py-2'>
      <MotionNumber
        value={shareAmount}
        suffix='%'
        className='text-muted-foreground text-xs'
      />
      <span
        className={cn(
          'truncate text-[13px] font-medium',
          isMuted && 'text-muted-foreground font-normal'
        )}
      >
        {label}
      </span>
      <DurationFigure minutes={minutes} className='text-[13px]' />
      <span className='col-start-2 col-end-4'>
        <ShareMeter share={share} tone={tone} transition={transition} />
      </span>
    </div>
  );
}

type ProjectRankingProps = {
  rows: RankedProject[];
  other: OtherProjects | null;
  emptyLine: string;
};

/** Shares read as text first: percentage, name, a thin meter, the time. Rows travel when the ranking changes. */
export function ProjectRanking({
  rows,
  other,
  emptyLine,
}: ProjectRankingProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);
  const moveTransition = moveTransitionOf(shouldReduceMotion);
  const isEmpty = rows.length === 0;
  const rowTransition = { layout: moveTransition };

  return (
    <div className='flex flex-col'>
      {isEmpty && (
        <p className='text-muted-foreground py-6 text-center text-[13px] text-balance'>
          {emptyLine}
        </p>
      )}
      <ol className='flex flex-col'>
        <AnimatePresence initial={false}>
          {rows.map((row, rank) => (
            <motion.li
              key={row.id}
              layout='position'
              variants={rowVariants}
              initial='hidden'
              animate='shown'
              exit='hidden'
              transition={rowTransition}
            >
              <RankRow
                label={row.name}
                minutes={row.minutes}
                share={row.share}
                tone={meterToneOf(rank)}
                transition={moveTransition}
              />
            </motion.li>
          ))}
        </AnimatePresence>
      </ol>
      <AnimatePresence initial={false}>
        {other && (
          <motion.div
            key='other'
            layout='position'
            variants={rowVariants}
            initial='hidden'
            animate='shown'
            exit='hidden'
            transition={rowTransition}
          >
            <RankRow
              label={otherLabelOf(other.count)}
              minutes={other.minutes}
              share={other.share}
              tone='bg-foreground/15'
              transition={moveTransition}
              isMuted
            />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';

import { durationPartsOf, formatDuration } from './weekly-figures';

const TWO_DIGITS: Intl.NumberFormatOptions = { minimumIntegerDigits: 2 };

type DurationFigureProps = {
  minutes: number;
  className?: string;
};

/** Hours and minutes roll as two numbers, but a screen reader hears the duration once. */
export function DurationFigure({ minutes, className }: DurationFigureProps) {
  const parts = durationPartsOf(minutes);
  const text = formatDuration(minutes);

  return (
    <span
      className={cn(
        'inline-flex items-baseline whitespace-nowrap tabular-nums',
        className
      )}
    >
      <span className='sr-only'>{text}</span>
      <span aria-hidden='true'>
        <MotionNumber value={parts.hours} suffix='h' />{' '}
        <MotionNumber value={parts.minutes} format={TWO_DIGITS} suffix='m' />
      </span>
    </span>
  );
}

import {
  MEMBERS,
  MEMBER_WEEKS,
  PROJECTS,
  WEEKS,
  type Member,
  type MemberId,
  type ProjectId,
  type Week,
  type WeekId,
} from './data';

export type Scope = 'everyone' | MemberId;

export type WeekQuery = { weekId: WeekId; scope: Scope };

export type DayBar = {
  axisLabel: string;
  label: string;
  minutes: number;
  isToday: boolean;
  isAhead: boolean;
};

export type RankedProject = {
  id: ProjectId;
  name: string;
  minutes: number;
  share: number;
};

export type OtherProjects = {
  count: number;
  minutes: number;
  share: number;
};

const RANKED_ROWS = 4;

const WORKING_DAYS = 5;

export function weekOf(weekId: WeekId) {
  const week = WEEKS.find((candidate) => candidate.id === weekId);
  if (week) {
    return week;
  }
  return WEEKS[0];
}

export function memberOf(scope: Scope): Member | null {
  const member = MEMBERS.find((candidate) => candidate.id === scope);
  if (member) {
    return member;
  }
  return null;
}

function membersIn(scope: Scope): MemberId[] {
  if (scope === 'everyone') {
    return MEMBERS.map((member) => member.id);
  }
  return [scope];
}

function sumOf(values: number[]) {
  return values.reduce((total, value) => total + value, 0);
}

function isAheadOf(week: Week, index: number) {
  if (week.todayIndex === null) {
    return false;
  }
  return index > week.todayIndex;
}

export function dayBarsOf(query: WeekQuery): DayBar[] {
  const week = weekOf(query.weekId);
  const memberIds = membersIn(query.scope);
  return week.days.map((day, index) => {
    const dayMinutes = memberIds.map(
      (memberId) => MEMBER_WEEKS[memberId][query.weekId].days[index]
    );
    const minutes = sumOf(dayMinutes);
    const isToday = week.todayIndex === index;
    const isAhead = isAheadOf(week, index);
    return {
      axisLabel: `${day.short} ${day.date}`,
      label: `${day.name} ${day.date} ${day.month}`,
      minutes,
      isToday,
      isAhead,
    };
  });
}

export function totalMinutesOf(bars: DayBar[]) {
  const minutes = bars.map((bar) => bar.minutes);
  return sumOf(minutes);
}

/** Monday to Friday, counted up to today while the week is running. */
export function workingDaysSoFarOf(week: Week) {
  if (week.todayIndex === null) {
    return WORKING_DAYS;
  }
  const daysSoFar = week.todayIndex + 1;
  return Math.min(daysSoFar, WORKING_DAYS);
}

/** Weekend time stays in the total but not in the average of a working day. */
export function averageWorkdayMinutesOf(bars: DayBar[], week: Week) {
  const workingDays = workingDaysSoFarOf(week);
  const weekdayBars = bars.slice(0, WORKING_DAYS);
  const weekdayMinutes = totalMinutesOf(weekdayBars);
  const average = weekdayMinutes / workingDays;
  return Math.round(average);
}

function addMinutes(
  totals: Map<ProjectId, number>,
  projectId: ProjectId,
  minutes: number
) {
  const current = totals.get(projectId) ?? 0;
  const next = current + minutes;
  totals.set(projectId, next);
}

function addMemberWeek(
  totals: Map<ProjectId, number>,
  memberId: MemberId,
  weekId: WeekId
) {
  const memberWeek = MEMBER_WEEKS[memberId][weekId];
  const weekTotal = sumOf(memberWeek.days);
  const lastMixIndex = memberWeek.mix.length - 1;
  let allocated = 0;
  memberWeek.mix.forEach((entry, index) => {
    const isLast = index === lastMixIndex;
    if (isLast) {
      const remainder = weekTotal - allocated;
      addMinutes(totals, entry.projectId, remainder);
      return;
    }
    const rawMinutes = weekTotal * entry.share;
    const minutes = Math.round(rawMinutes);
    allocated += minutes;
    addMinutes(totals, entry.projectId, minutes);
  });
}

function projectNameOf(projectId: ProjectId) {
  const project = PROJECTS.find((candidate) => candidate.id === projectId);
  if (project) {
    return project.name;
  }
  return projectId;
}

function shareOf(minutes: number, totalMinutes: number) {
  if (totalMinutes === 0) {
    return 0;
  }
  return minutes / totalMinutes;
}

function byMinutesThenName(first: RankedProject, second: RankedProject) {
  const difference = second.minutes - first.minutes;
  if (difference !== 0) {
    return difference;
  }
  return first.name.localeCompare(second.name);
}

export function rankingOf(query: WeekQuery) {
  const totals = new Map<ProjectId, number>();
  const memberIds = membersIn(query.scope);
  memberIds.forEach((memberId) =>
    addMemberWeek(totals, memberId, query.weekId)
  );
  const allMinutes = Array.from(totals.values());
  const totalMinutes = sumOf(allMinutes);
  const entries = Array.from(totals.entries());
  const projects = entries.map(([projectId, minutes]) => ({
    id: projectId,
    name: projectNameOf(projectId),
    minutes,
    share: shareOf(minutes, totalMinutes),
  }));
  const sorted = [...projects].sort(byMinutesThenName);
  const rows = sorted.slice(0, RANKED_ROWS);
  const rest = sorted.slice(RANKED_ROWS);
  const restEach = rest.map((project) => project.minutes);
  const restMinutes = sumOf(restEach);
  const other = otherOf(rest.length, restMinutes, totalMinutes);
  return { rows, other, projectCount: sorted.length };
}

function otherOf(
  count: number,
  minutes: number,
  totalMinutes: number
): OtherProjects | null {
  if (count === 0) {
    return null;
  }
  const share = shareOf(minutes, totalMinutes);
  return { count, minutes, share };
}

export function durationPartsOf(totalMinutes: number) {
  const rawHours = totalMinutes / 60;
  const hours = Math.floor(rawHours);
  const minutes = totalMinutes % 60;
  return { hours, minutes };
}

export function formatDuration(totalMinutes: number) {
  const { hours, minutes } = durationPartsOf(totalMinutes);
  const paddedMinutes = String(minutes).padStart(2, '0');
  return `${hours}h ${paddedMinutes}m`;
}

export function csvRowsOf(bars: DayBar[]) {
  const header = ['Day', 'Tracked time', 'Minutes'];
  const rows = bars.map((bar) => {
    const duration = formatDuration(bar.minutes);
    const minutes = String(bar.minutes);
    return [bar.label, duration, minutes];
  });
  return [header, ...rows];
}

'use client';

import { useState } from 'react';

import { CircleCheckIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Skeleton } from '@/registry/ndeko/ui/skeleton';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { PROJECT, SPRINTS, type Sprint, type SprintId } from './data';
import {
  csvRowsOf,
  goalOf,
  needsAttention,
  rowsOf,
  sprintOf,
  totalsOf,
} from './health-figures';
import { GoalCard } from './goal-card';
import {
  ExportButton,
  PeriodSwitch,
  REPORT_SURFACE,
  ReportToolbar,
  downloadCsv,
  useSimulatedLoad,
  type PeriodOption,
} from './report-frame';
import { WorkstreamTable } from './workstream-table';

type RowFilter = 'all' | 'attention';

const SPRINT_OPTIONS: PeriodOption<SprintId>[] = SPRINTS.map((sprint) => ({
  id: sprint.id,
  label: `Sprint ${sprint.number}`,
}));

const CURRENT_SPRINT: SprintId = 's23';

const SKELETON_ROWS = ['first', 'second', 'third', 'fourth', 'fifth'];

function sprintKeyOf(sprintId: SprintId) {
  return sprintId;
}

function isRowFilter(value: unknown): value is RowFilter {
  const isAll = value === 'all';
  const isAttention = value === 'attention';
  return isAll || isAttention;
}

function peopleLabelOf(count: number) {
  if (count === 1) {
    return '1 person';
  }
  return `${count} people`;
}

function blockedLabelOf(count: number) {
  if (count === 0) {
    return 'nothing blocked';
  }
  if (count === 1) {
    return '1 task blocked';
  }
  return `${count} tasks blocked`;
}

function workstreamCountOf(count: number) {
  if (count === 1) {
    return '1 workstream';
  }
  return `${count} workstreams`;
}

function calmLineOf(sprint: Sprint) {
  const isRunning = sprint.daysElapsed < sprint.workingDays;
  if (isRunning) {
    return `Every workstream is on track in sprint ${sprint.number}`;
  }
  return `Every workstream was on track in sprint ${sprint.number}`;
}

function visibleRowsOf<Row>(
  isAttentionView: boolean,
  rows: Row[],
  attentionRows: Row[]
) {
  if (isAttentionView) {
    return attentionRows;
  }
  return rows;
}

function totalsWhen<Value>(isShown: boolean, value: Value) {
  if (isShown) {
    return value;
  }
  return null;
}

function HealthSkeleton() {
  return (
    <div aria-hidden='true' className='flex flex-col gap-4'>
      <div className={cn(REPORT_SURFACE, 'flex flex-col gap-4 p-5')}>
        <Skeleton className='h-3 w-24' />
        <Skeleton className='h-4 w-64 max-w-full' />
        <Skeleton className='h-7 w-40' />
        <Skeleton className='h-2 w-full rounded-full' />
        <Skeleton className='h-3 w-56 max-w-full' />
      </div>
      <div className={cn(REPORT_SURFACE, 'flex flex-col gap-3 p-5')}>
        <Skeleton className='h-3.5 w-28' />
        {SKELETON_ROWS.map((row) => (
          <Skeleton key={row} className='h-8 w-full' />
        ))}
      </div>
    </div>
  );
}

export function ProjectHealthPage() {
  const load = useSimulatedLoad<SprintId>(CURRENT_SPRINT, sprintKeyOf);
  const [filter, setFilter] = useState<RowFilter>('all');
  const shownSprintId = load.loaded ?? load.requested;
  const sprint = sprintOf(shownSprintId);
  const rows = rowsOf(sprint);
  const totals = totalsOf(rows);
  const goal = goalOf(sprint, totals);
  const attentionRows = rows.filter(needsAttention);
  const isAttentionView = filter === 'attention';
  const visibleRows = visibleRowsOf(isAttentionView, rows, attentionRows);
  const isCalm = attentionRows.length === 0;
  const showsCalmState = isAttentionView && isCalm;
  const showsTotals = !isAttentionView;
  const shownTotals = totalsWhen(showsTotals, totals);
  const peopleLabel = peopleLabelOf(PROJECT.peopleCount);
  const meta = `${PROJECT.release} · ${sprint.rangeLabel} · ${peopleLabel}`;
  const workstreamLabel = workstreamCountOf(rows.length);
  const blockedLabel = blockedLabelOf(totals.blocked);
  const calmLine = calmLineOf(sprint);

  function changeFilter(value: unknown) {
    if (isRowFilter(value)) {
      setFilter(value);
    }
  }

  function showAll() {
    setFilter('all');
  }

  function exportHealth() {
    const csvRows = csvRowsOf(rows);
    const fileName = `${PROJECT.fileSlug}-sprint-${sprint.number}.csv`;
    downloadCsv(fileName, csvRows);
  }

  return (
    <div className='min-h-0 w-full flex-1 overflow-y-auto'>
      <ReportToolbar title={PROJECT.name} meta={meta}>
        <ExportButton disabled={load.isFirstLoad} onExport={exportHealth} />
      </ReportToolbar>
      <div className='mx-auto flex w-full max-w-4xl flex-col gap-4 px-4 py-5 md:px-6'>
        <PeriodSwitch
          label='Sprint'
          options={SPRINT_OPTIONS}
          value={load.requested}
          isUpdating={load.isUpdating}
          onValueChange={load.request}
        />
        {load.isFirstLoad && <HealthSkeleton />}
        {!load.isFirstLoad && (
          <div aria-busy={load.isUpdating} className='flex flex-col gap-4'>
            <GoalCard sprint={sprint} goal={goal} />
            <section
              aria-label='Workstreams'
              className={cn(REPORT_SURFACE, 'flex flex-col gap-3 pt-4 pb-1')}
            >
              <div className='flex flex-wrap items-center justify-between gap-x-3 gap-y-2 px-4'>
                <div className='flex flex-col gap-0.5'>
                  <h2 className='text-sm font-medium'>Workstreams</h2>
                  <p className='text-muted-foreground text-xs tabular-nums'>
                    {`${workstreamLabel}, ${blockedLabel}`}
                  </p>
                </div>
                <Tabs value={filter} onValueChange={changeFilter}>
                  <TabsList
                    variant='segmented'
                    aria-label='Workstreams to show'
                  >
                    <TabsTab value='all'>All</TabsTab>
                    <TabsTab value='attention'>
                      Needs attention
                      <span className='text-muted-foreground text-xs tabular-nums'>
                        {attentionRows.length}
                      </span>
                    </TabsTab>
                  </TabsList>
                </Tabs>
              </div>
              <WorkstreamTable
                rows={visibleRows}
                totals={shownTotals}
                emptyState={
                  showsCalmState && (
                    <div className='flex flex-col items-center gap-3 px-4 py-10 text-center'>
                      <span className='keycap-3d text-success-foreground flex size-9 items-center justify-center rounded-lg'>
                        <CircleCheckIcon />
                      </span>
                      <p className='text-[13px] font-medium text-balance'>
                        {calmLine}
                      </p>
                      <Button variant='outline' size='sm' onClick={showAll}>
                        Show all workstreams
                      </Button>
                    </div>
                  )
                }
              />
            </section>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Sprint } from './data';
import { percentAmountOf, type Goal, type GoalTone } from './health-figures';

const MOVE_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1],
};

const MARKER_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const MARKER_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

const INSTANT: Transition = { duration: 0 };

const VERDICT_TONE: Record<GoalTone, string> = {
  good: 'text-success-foreground',
  behind: 'text-warning-foreground',
  neutral: 'text-foreground',
};

function moveTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE_TRANSITION;
}

function taskWordOf(count: number) {
  if (count === 1) {
    return 'task';
  }
  return 'tasks';
}

function percentTextOf(share: number) {
  const percent = share * 100;
  return `${percent}%`;
}

type GoalMeterProps = {
  goal: Goal;
  transition: Transition;
};

/** Done against planned, with a marker where the team should be by today. Both slide into place. */
function GoalMeter({ goal, transition }: GoalMeterProps) {
  const hiddenShare = 1 - goal.share;
  const hiddenText = percentTextOf(hiddenShare);
  const fillOffset = `-${hiddenText}`;
  const taskWord = taskWordOf(goal.planned);
  const valueText = `${goal.done} of ${goal.planned} ${taskWord} done`;
  const hasMarker = goal.expectedShare !== null;
  const markerShare = goal.expectedShare ?? 0;
  const markerOffset = percentTextOf(markerShare);

  return (
    <div
      role='progressbar'
      aria-label='Sprint progress'
      aria-valuemin={0}
      aria-valuemax={goal.planned}
      aria-valuenow={goal.done}
      aria-valuetext={valueText}
      className='bg-foreground/[0.08] relative h-2 rounded-full'
    >
      <span className='absolute inset-0 overflow-hidden rounded-full'>
        <motion.span
          initial={false}
          animate={{ x: fillOffset }}
          transition={transition}
          className='bg-primary absolute inset-0 rounded-full'
        />
      </span>
      <AnimatePresence initial={false}>
        {hasMarker && (
          <motion.span
            key='marker'
            aria-hidden='true'
            initial={{ opacity: 0, x: markerOffset }}
            animate={{
              opacity: 1,
              x: markerOffset,
              transition: { opacity: MARKER_IN, x: transition },
            }}
            exit={{ opacity: 0, transition: MARKER_OUT }}
            className='pointer-events-none absolute -inset-y-1 left-0 w-full'
          >
            <span className='bg-foreground ring-card absolute inset-y-0 left-0 w-0.5 -translate-x-1/2 rounded-full ring-2' />
          </motion.span>
        )}
      </AnimatePresence>
    </div>
  );
}

type GoalCardProps = {
  sprint: Sprint;
  goal: Goal;
};

export function GoalCard({ sprint, goal }: GoalCardProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const transition = moveTransitionOf(shouldReduceMotion);
  const shareAmount = percentAmountOf(goal.share);
  const hasMarker = goal.expectedShare !== null;
  const taskWord = taskWordOf(goal.planned);

  return (
    <section
      aria-label={`Sprint ${sprint.number} goal`}
      className='surface-brand flex flex-col gap-4 rounded-xl p-5'
    >
      <div className='flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1'>
        <p className='text-muted-foreground text-xs font-medium'>
          {`Sprint ${sprint.number} goal`}
        </p>
        <span className='text-muted-foreground text-xs'>
          Illustrative figures
        </span>
      </div>
      <p className='text-base font-semibold text-balance'>{sprint.goal}</p>
      <div className='flex flex-wrap items-baseline justify-between gap-x-6 gap-y-1'>
        <p className='flex items-baseline gap-1.5'>
          <MotionNumber value={goal.done} className='text-2xl font-semibold' />
          <span className='text-muted-foreground text-[13px]'>of</span>
          <MotionNumber
            value={goal.planned}
            className='text-[13px] font-medium'
          />
          <span className='text-muted-foreground text-[13px]'>
            {`${taskWord} done`}
          </span>
        </p>
        <MotionNumber
          value={shareAmount}
          suffix='%'
          className='text-lg font-semibold'
        />
      </div>
      <GoalMeter goal={goal} transition={transition} />
      <div className='flex flex-wrap items-center justify-between gap-x-4 gap-y-1 text-xs'>
        <span className={cn('font-medium', VERDICT_TONE[goal.tone])}>
          {goal.verdict}
        </span>
        <span className='text-muted-foreground flex items-center gap-1.5'>
          {hasMarker && (
            <span
              aria-hidden='true'
              className='bg-foreground inline-block h-2.5 w-0.5 rounded-full'
            />
          )}
          {goal.timeLine}
        </span>
      </div>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';

import { HEALTH_META, type Lead } from './data';
import {
  percentAmountOf,
  type Totals,
  type WorkstreamRow,
} from './health-figures';

const TABLE_GRID =
  'grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 px-4 sm:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)_2.75rem_2.75rem_3.5rem_minmax(5.5rem,1fr)_6rem]';

const WIDE_CELL = 'hidden sm:flex';

const FIGURE_CELL = 'hidden justify-end text-[13px] sm:flex';

const ROW_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const ROW_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const MOVE_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

const ROW_VARIANTS: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: ROW_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: ROW_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: ROW_OUT },
  shown: { opacity: 1, transition: ROW_IN },
};

function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_VARIANTS;
}

function moveTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE_TRANSITION;
}

function firstNameOf(lead: Lead) {
  const [firstName] = lead.name.split(' ');
  return firstName;
}

type FigureProps = {
  value: number;
  isQuiet?: boolean;
};

function Figure({ value, isQuiet }: FigureProps) {
  return (
    <MotionNumber
      value={value}
      className={cn(isQuiet && 'text-muted-foreground')}
    />
  );
}

type ProgressCellProps = {
  share: number;
  transition: Transition;
};

function ProgressCell({ share, transition }: ProgressCellProps) {
  const hiddenShare = 1 - share;
  const hiddenPercent = hiddenShare * 100;
  const offset = `-${hiddenPercent}%`;
  const shareAmount = percentAmountOf(share);

  return (
    <div role='cell' className={cn(WIDE_CELL, 'items-center gap-2')}>
      <span className='bg-foreground/[0.08] relative block h-1 min-w-0 flex-1 overflow-hidden rounded-full'>
        <motion.span
          initial={false}
          animate={{ x: offset }}
          transition={transition}
          className='bg-primary absolute inset-0 rounded-full'
        />
      </span>
      <MotionNumber
        value={shareAmount}
        suffix='%'
        className='text-muted-foreground w-9 justify-end text-xs'
      />
    </div>
  );
}

function LeadCell({ lead }: { lead: Lead }) {
  return (
    <div role='cell' className={cn(WIDE_CELL, 'min-w-0 items-center gap-2')}>
      <Avatar className='size-6 text-[10px]'>
        {lead.avatar && <AvatarImage src={lead.avatar} alt='' />}
        <AvatarFallback>{lead.initials}</AvatarFallback>
      </Avatar>
      <span className='truncate text-[13px]'>{firstNameOf(lead)}</span>
    </div>
  );
}

function HealthChip({ row }: { row: WorkstreamRow }) {
  const meta = HEALTH_META[row.health];

  return (
    <Chip color={meta.color}>
      <span aria-hidden='true' className='size-1.5 rounded-full bg-(--chip)' />
      {meta.label}
    </Chip>
  );
}

type WorkstreamTableProps = {
  rows: WorkstreamRow[];
  totals: Totals | null;
  emptyState?: React.ReactNode;
};

/** One grid for the header, the rows and the totals, so the figures line up. Rows enter and leave in place. */
export function WorkstreamTable({
  rows,
  totals,
  emptyState,
}: WorkstreamTableProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);
  const transition = moveTransitionOf(shouldReduceMotion);

  return (
    <div role='table' aria-label='Workstreams' className='flex flex-col'>
      <div role='rowgroup'>
        <div
          role='row'
          className={cn(
            TABLE_GRID,
            'hairline-b border-border text-muted-foreground h-9 text-xs font-medium'
          )}
        >
          <span role='columnheader'>Workstream</span>
          <span role='columnheader' className={WIDE_CELL}>
            Lead
          </span>
          <span role='columnheader' className={FIGURE_CELL}>
            Done
          </span>
          <span role='columnheader' className={FIGURE_CELL}>
            Open
          </span>
          <span role='columnheader' className={FIGURE_CELL}>
            Blocked
          </span>
          <span role='columnheader' className={WIDE_CELL}>
            Progress
          </span>
          <span
            role='columnheader'
            className='flex justify-end sm:justify-start'
          >
            Health
          </span>
        </div>
      </div>
      <div role='rowgroup' className='hairline-divide-y divide-border'>
        <AnimatePresence initial={false}>
          {rows.map((row) => {
            const isBlockFree = row.blocked === 0;
            const leadFirstName = firstNameOf(row.lead);
            const phoneLine = `${row.done} of ${row.planned} done · ${leadFirstName}`;

            return (
              <motion.div
                key={row.id}
                variants={rowVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
              >
                <div role='row' className={cn(TABLE_GRID, 'min-h-12 py-2.5')}>
                  <div role='cell' className='flex min-w-0 flex-col gap-0.5'>
